revision_guidance:
{
  "overall_direction": "Refine the skill toward stricter grounding and less speculative planning. Keep the decomposition/dependency strengths, but sharply narrow any guidance that encourages over-expansion when the tool surface is limited. The main goal next round is to preserve compact, tool-native plans and prevent invented parameters, placeholder calls, or unsupported numeric claims.",
  "keep": [
    {
      "rule": "Decompose before querying. Split the request into independent subproblems, then map each one to the narrowest relevant tool or data source.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "why": "The structured branch decomposition was helpful and should be preserved, even though grounding failed."
    },
    {
      "rule": "Separate parallel from dependent work. Query independent branches in parallel; delay any branch that needs a prerequisite result until that result is available.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "why": "Parallel branch planning was a genuine strength and did not cause the regressions."
    },
    {
      "rule": "Reuse shared inputs. If multiple branches need the same identifier, date range, or entity list, carry it forward rather than re-deriving it.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "why": "This supports efficient planning and is not implicated in the failures."
    },
    {
      "rule": "Verify intermediate values. Check counts, thresholds, versions, schema fields, or formula inputs before combining results.",
      "evidence_case_ids": [
        "math_mcp_000"
      ],
      "why": "Intermediate verification is useful, but it should be kept in a grounded form rather than expanded into unsupported calculations."
    },
    {
      "rule": "Close the loop. Carry every dependency through to a complete structured plan and final answer that covers all requested components.",
      "evidence_case_ids": [
        "math_mcp_000",
        "dex_paprika_001"
      ],
      "why": "Completeness matters, but this rule should be constrained so it does not force unsupported branches."
    }
  ],
  "remove_or_soften": [
    {
      "rule": "Start with high-signal facts. Gather the easiest, most discriminative evidence first so later steps can be narrowed instead of guessed.",
      "evidence_case_ids": [
        "medical_calculator_000",
        "math_mcp_000",
        "dex_paprika_001"
      ],
      "why": "This is too weakly bounded and can be interpreted as license to keep expanding the plan after the supported surface is already clear. In the regressions, that pattern led to extra unsupported steps, placeholder calls, and invented fields.",
      "proposed_replacement": "SOFTEN to: Start with high-signal facts only when they are directly supported by the tool surface; do not expand into extra branches, placeholders, or unsupported metrics once the supported subset is identified."
    },
    {
      "rule": "The task needs multiple dependent lookups or calculations, but the plan stops after the first plausible step. Counter-action: Enumerate every prerequisite and downstream step, then ensure the dependency chain reaches the final synthesis.",
      "evidence_case_ids": [
        "medical_calculator_000",
        "math_mcp_000"
      ],
      "why": "This over-encourages exhaustive chaining even when the tool cannot support the requested quantities. In the regressions, it pushed the planner into fabricated calculations and malformed parameterization instead of stopping at the supported subset.",
      "proposed_replacement": "SOFTEN to: Enumerate only the prerequisites and downstream steps that can be expressed with the known tool surface; if a requested quantity is unsupported, stop the chain there and report it as unavailable."
    },
    {
      "rule": "A comparison task is answered from one source when multiple sources or categories are implied. Counter-action: Split the evidence by source/category first, then reconcile the verified pieces only after each branch has been checked.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "why": "The comparison/decomposition idea is good, but in the failing case it contributed to over-branching with invented filters and query shapes. It needs a tighter grounding constraint so branch-splitting does not become speculative tool design.",
      "proposed_replacement": "SOFTEN to: Split evidence by source/category only when the tool surface explicitly supports those branches; otherwise keep the plan within the documented query forms."
    }
  ],
  "add_or_sharpen": [
    {
      "rule": "Before proposing any parameter or field, restrict yourself to the exact tool surface shown in the prompt; if a filter or metric is not listed, omit it rather than inventing a plausible MCP argument.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "section": "Failure lessons"
    },
    {
      "rule": "Do not emit placeholder calls, null arguments, or invented parameter names for unsupported metrics; either use only supported calculations or state the missing result is unavailable.",
      "evidence_case_ids": [
        "medical_calculator_000",
        "math_mcp_000"
      ],
      "section": "Failure lessons"
    },
    {
      "rule": "When the toolset cannot directly compute a requested quantity, do not fabricate numeric results or pseudo-verification; mark the quantity uncomputable and continue only with supported outputs.",
      "evidence_case_ids": [
        "medical_calculator_000",
        "math_mcp_000"
      ],
      "section": "Failure lessons"
    },
    {
      "rule": "Keep dependency chains tool-realistic: do not reference intermediate outputs or schema fields before they are actually produced by a tool call.",
      "evidence_case_ids": [
        "dex_paprika_001"
      ],
      "section": "Successful experiences"
    }
  ],
  "length_budget_note": "Yes: the body should be compressed slightly by trimming overlapping failure lessons and folding the new grounding guardrails into one or two concise bullets, keeping the final skill comfortably within 300-600 words."
}
